package com.bank.recursive;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class RecursiveGenericsTest {

    // Abstract builder with recursive generic
    @SuppressWarnings("unchecked")
    static abstract class Builder<T extends Builder<T>> {
        String accountId;
        T accountId(String id) { this.accountId = id; return (T) this; }
    }

    // Concrete builder
    static class TradeBuilder extends Builder<TradeBuilder> {
        String symbol;
        int quantity;
        TradeBuilder symbol(String s) { this.symbol = s; return this; }
        TradeBuilder quantity(int q) { this.quantity = q; return this; }
    }

    @Test
    void fluentBuilder_chainsCorrectly() {
        TradeBuilder builder = new TradeBuilder()
            .accountId("SAV2001")    // returns TradeBuilder (not Builder!)
            .symbol("RELIANCE")       // available because accountId returned TradeBuilder!
            .quantity(100);

        assertThat(builder.accountId).isEqualTo("SAV2001");
        assertThat(builder.symbol).isEqualTo("RELIANCE");
        assertThat(builder.quantity).isEqualTo(100);
    }

    @Test
    void enum_selfBounded_compareTo() {
        enum Priority { LOW, MEDIUM, HIGH }
        // Priority extends Enum<Priority>
        // compareTo(Priority o) — only accepts Priority!
        assertThat(Priority.HIGH.compareTo(Priority.LOW)).isGreaterThan(0);

    }
}
